index 000000000..45544261c
--- /dev/null
+++ b/packages/workflow/test/native-evaluation-vm2-skip.test.ts
@@ -0,0 +1,88 @@
+import type { ObservabilityProvider } from '@n8n/expression-runtime';
+import { EXPRESSION_METRICS } from '@n8n/expression-runtime';
+import { mock } from 'vitest-mock-extended';
+
+import { nodeTypes } from './ExpressionExtensions/helpers';
+import { Expression } from '../src/expression';
+import { FUNCTION_ITEM_NODE_TYPE, FUNCTION_NODE_TYPE } from '../src/constants';
+import { Workflow } from '../src/workflow';
+
+const engine = process.env.N8N_EXPRESSION_ENGINE as 'vm' | 'legacy' | 'quickjs';
+
+describe('Expression - native evaluation with vm2 sandbox nodes', () => {
+	const observability = mock<ObservabilityProvider>({
+		metrics: { counter: vi.fn(), gauge: vi.fn(), histogram: vi.fn() },
+	});
+
+	beforeAll(async () => {
+		await Expression.initExpressionEngine({
+			engine,
+			poolSize: 1,
+			maxCodeCacheSize: 1024,
+			bridgeTimeout: 5000,
+			bridgeMemoryLimit: 128,
+			nativeEvaluation: true,
+			observability,
+		});
+	});
+
+	afterAll(() => {
+		Expression.setNativeEvaluation(false);
+	});
+
+	afterEach(() => {
+		vi.mocked(observability.metrics.counter).mockClear();
+	});
+
+	const workflowWith = (type: string) =>
+		new Workflow({
+			nodes: [
+				{
+					name: 'node',
+					typeVersion: 1,
+					type: 'test.set',
+					id: 'uuid-1',
+					position: [0, 0],
+					parameters: {},
+				},
+				{ name: 'other', typeVersion: 1, type, id: 'uuid-2', position: [0, 0], parameters: {} },
+			],
+			connections: {},
+			active: false,
+			nodeTypes,
+		});
+
+	// The isolate is acquired per workflow, as the engine needs a held bridge.
+	const evaluate = async (workflow: Workflow, value: string) =>
+		await workflow.expression.withIsolate(async () =>
+			workflow.expression.getParameterValue(
+				value,
+				null,
+				0,
+				0,
+				'node',
+				[{ json: { name: 'a' } }],
+				'manual',
+				{},
+			),
+		);
+
+	test('a plain workflow is evaluated natively', async () => {
+		expect(await evaluate(workflowWith('test.set'), '={{ $json.name }}')).toBe('a');
+
+		expect(observability.metrics.counter).toHaveBeenCalledExactlyOnceWith(
+			EXPRESSION_METRICS.nativeEvaluations.name,
+			1,
+			{ result: 'handled', reason: 'none' },
+		);
+	});
+
+	test.each([
+		['Function', FUNCTION_NODE_TYPE],
+		['FunctionItem', FUNCTION_ITEM_NODE_TYPE],
+	])('a workflow with a %s node skips native evaluation', async (_label, type) => {
+		expect(await evaluate(workflowWith(type), '={{ $json.name }}')).toBe('a');
+
+		expect(observability.metrics.counter).not.toHaveBeenCalled();
+	});
+});
